25	function mulberry32(seed: number): () => number {
26	  let t = seed >>> 0;
27	  return () => {
28	    t += 0x6d2b79f5;
29	    let r = Math.imul(t ^ (t >>> 15), 1 | t);
30	    r ^= r + Math.imul(r ^ (r >>> 7), 61 | r);
31	    return ((r ^ (r >>> 14)) >>> 0) / 4294967296;
32	  };
33	}
