  state.player.yaw = 0;
  state.player.pitch = 0;
  spawnTestMob(engine, "zombie", true, { x: 0, y: EYE_HEIGHT, z: -2 });
  state.mobs[state.mobs.length - 1].hp = 1; // one fist hit (6 dmg) kills it
